revision.text:
/* Template:Infobox/styles.css: the look of every infobox (TemplateStyles).
   Colours are see-through greys and inherited text, so the boxes follow
   Citizen's light and dark modes without needing its CSS variables. */

.rp-infobox {
	float: right;
	clear: right;
	box-sizing: border-box;
	width: 400px;
	max-width: 100%;
	margin: 0 0 1.5em 1.5em;
	border: 1px solid rgba( 127, 127, 127, 0.28 );
	border-radius: 12px;
	background: rgba( 127, 127, 127, 0.07 );
	overflow: hidden;
	font-size: 0.875rem;
	line-height: 1.45;
}

/* Pictures */
.rp-infobox .rp-ib-image {
	text-align: center;
	background: rgba( 127, 127, 127, 0.1 );
}
.rp-infobox .rp-ib-image img {
	display: block;
	width: 100%;
	height: auto;
	max-height: 460px;
	object-fit: cover;
}
.rp-infobox .rp-ib-image a {
	display: block;
}
.rp-infobox .rp-ib-caption {
	padding: 6px 16px;
	font-size: 0.8125rem;
	opacity: 0.75;
}
/* Portrait tabs */
.rp-infobox .rp-ib-tabs .tabber {
	margin: 0;
}

/* Heading */
.rp-infobox .rp-ib-head {
	padding: 14px 16px 10px;
}
.rp-infobox .rp-ib-kind {
	font-size: 0.875rem;
	opacity: 0.75;
}
.rp-infobox .rp-ib-title {
	margin-top: 2px;
	font-size: 1.5rem;
	font-weight: 500;
	line-height: 1.2;
}
.rp-infobox .rp-ib-badges {
	display: flex;
	flex-wrap: wrap;
	gap: 6px;
	margin-top: 10px;
}
.rp-infobox .rp-ib-note {
	margin-top: 8px;
	font-size: 0.8125rem;
	opacity: 0.75;
}

/* Badges */
.rp-badge {
	display: inline-block;
	padding: 2px 10px;
	border-radius: 999px;
	border: 1px solid rgba( 127, 127, 127, 0.35 );
	background: rgba( 127, 127, 127, 0.12 );
	font-size: 0.75rem;
	font-weight: 600;
	line-height: 1.6;
	white-space: nowrap;
}
/* Badges link to their categories but keep their own colours */
.rp-badge a,
.rp-badge a:visited {
	color: inherit;
	text-decoration: none;
}
.rp-badge:hover {
	filter: brightness( 1.15 );
}
.rp-badge--active { background: rgba( 34, 197, 94, 0.16 ); border-color: rgba( 34, 197, 94, 0.5 ); color: #1f9d55; }
.rp-badge--inactive { background: rgba( 148, 163, 184, 0.18 ); border-color: rgba( 148, 163, 184, 0.55 ); }
.rp-badge--deceased { background: rgba( 239, 68, 68, 0.15 ); border-color: rgba( 239, 68, 68, 0.5 ); color: #dc4040; }
.rp-badge--defunct { background: rgba( 239, 68, 68, 0.12 ); border-color: rgba( 239, 68, 68, 0.45 ); color: #dc4040; }
.rp-badge--civilian { background: rgba( 59, 130, 246, 0.14 ); border-color: rgba( 59, 130, 246, 0.5 ); color: #3b82f6; }
.rp-badge--criminal { background: rgba( 236, 72, 153, 0.14 ); border-color: rgba( 236, 72, 153, 0.5 ); color: #db2777; }
.rp-badge--public-sector { background: rgba( 14, 165, 233, 0.14 ); border-color: rgba( 14, 165, 233, 0.5 ); color: #0284c7; }
.rp-badge--official-server-event { background: rgba( 245, 158, 11, 0.16 ); border-color: rgba( 245, 158, 11, 0.55 ); color: #c27803; }

/* A thin coloured line along the top for the most important badge */
.rp-infobox.rp-status--deceased,
.rp-infobox.rp-status--defunct { border-top: 3px solid rgba( 239, 68, 68, 0.7 ); }
.rp-infobox.rp-type--official-server-event { border-top: 3px solid rgba( 245, 158, 11, 0.8 ); }

/* Rows */
.rp-infobox .rp-ib-section {
	padding: 0 16px 8px;
}
.rp-infobox .rp-ib-section + .rp-ib-section,
.rp-infobox .rp-ib-section.mw-collapsible {
	border-top: 1px solid rgba( 127, 127, 127, 0.22 );
}
.rp-infobox .rp-ib-row {
	display: flex;
	gap: 16px;
	padding: 6px 0;
}
.rp-infobox .rp-ib-label {
	flex: 0 0 38%;
	opacity: 0.75;
}
.rp-infobox .rp-ib-value {
	flex: 1;
	min-width: 0;
	text-align: right;
	overflow-wrap: anywhere;
}
.rp-infobox .rp-ib-value ul,
.rp-infobox .rp-ib-value ol {
	margin: 0;
	padding: 0;
	list-style: none;
}

/* Foldable sections: the title is the toggle */
.rp-infobox .rp-ib-section-title {
	display: flex;
	align-items: center;
	justify-content: space-between;
	float: none;
	margin: 0 -16px;
	padding: 12px 16px;
	font-size: 1rem;
	font-weight: 500;
	cursor: pointer;
	user-select: none;
}
.rp-infobox .rp-ib-section-title::after {
	content: '';
	width: 8px;
	height: 8px;
	margin-right: 4px;
	border-right: 2px solid currentColor;
	border-bottom: 2px solid currentColor;
	opacity: 0.6;
	transform: rotate( -135deg );
	transition: transform 0.2s;
}
.rp-infobox .mw-collapsed .rp-ib-section-title::after {
	transform: rotate( 45deg );
}

/* Problems with the values typed in */
.rp-infobox .rp-ib-problems {
	margin: 8px 16px 12px;
	padding: 8px 10px;
	border-radius: 8px;
	border: 1px solid rgba( 239, 68, 68, 0.5 );
	background: rgba( 239, 68, 68, 0.1 );
	font-size: 0.8125rem;
}

/* Phones and narrow windows: full width, above the text */
@media ( max-width: 720px ) {
	.rp-infobox {
		float: none;
		width: auto;
		margin: 0 0 1.5em;
	}
	.rp-infobox .rp-ib-image img {
		max-height: 320px;
	}
}
